export const EnrichmentInferenceWarningSchema = z.object({
    code: z.string().min(1),
    message: z.string(),
    severity: z.enum(['info', 'warning']),
}).passthrough();
// ----------------------------------------------------------------------------
// critiques — [F1] entries, [F2] CritiqueV3
